// ?parseBitInInt32@INI@@SAXPAV1@PAX1PBX@Z
void INI::parseBitInInt32(INI *ini, void * /*instance*/, void *store, const void *userData)
{
	unsigned int *s = (unsigned int *)store;
	unsigned int mask = (unsigned int)userData;

	if (ini->scanBool(ini->getNextToken(NULL)))
		*s |= mask;
	else
		*s &= ~mask;
}

// ---- from Code/GameEngine/Source/Common/System/INI_getNextQuotedAsciiString.cpp

AsciiString INI::getNextQuotedAsciiString()
{
	AsciiString result;
	char buff[INI::MAX_CHARS_PER_LINE];
	buff[0] = '\0';

	const char *token = getNextTokenOrNull(0);
	if (token != 0)
	{
		if (token[0] != '\"')
		{
			result.set(token);
		}
		else
		{
			Int strLen = 0;
			Bool done = false;
			if ((strLen = (Int)strlen(token)) > 1)
			{
				_mbscpy(reinterpret_cast<unsigned char *>(buff), reinterpret_cast<const unsigned char *>(&token[1]));
				if (buff[strLen - 2] == '\"')
				{
					buff[strLen - 2] = '\0';
					done = true;
				}
			}

			if (!done)
			{
				token = getNextToken(getSepsQuote());

				if (strlen(token) > 1 && token[1] != '\t')
				{
					_mbscat(reinterpret_cast<unsigned char *>(buff), reinterpret_cast<const unsigned char *>(" "));
					_mbscat(reinterpret_cast<unsigned char *>(buff), reinterpret_cast<const unsigned char *>(token));
				}
				else
				{
					Int buflen = (Int)strlen(buff);
					if (buff[buflen - 1] == '\"')
						buff[buflen - 1] = '\0';
				}
			}
			result.set(buff);
		}
	}
	return result;
}

